import './App.css';
import LightPillar from './LightPillar';
import { ParallaxProvider, Parallax } from 'react-scroll-parallax';

function App() {
  return (
    <ParallaxProvider>
      <div
        className="App"
        style={{
          background: '#000',
          color: 'white',
          overflowX: 'hidden',
        }}
      >

        {/* FIXED BACKGROUND */}
        <div
          id="pillar"
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100%',
            height: '100vh',
            zIndex: -1,
          }}
        >
          <LightPillar
            topColor="#ce466f"
            bottomColor="#ce466f"
            intensity={1}
            rotationSpeed={0.3}
            glowAmount={0.002}
            pillarWidth={3}
            pillarHeight={0.4}
            noiseIntensity={0.5}
            pillarRotation={25}
            interactive={false}
            mixBlendMode="screen"
            quality="high"
          />
        </div>

        {/* HERO */}
        <section
          id="hero"
          style={{
            height: '100vh',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
            alignItems: 'center',
            textAlign: 'center',
            position: 'relative',
            zIndex: 2,
          }}
        >
          <h1
            style={{
              fontSize: '4rem',
              marginBottom: '1rem',
            }}
          >
            Welcome to your Algorithm Learning Assistant!
          </h1>

          <p
            style={{
              opacity: 0.8,
              marginBottom: '2rem',
            }}
          >
            Completely open-source, and free!
          </p>

          <button
            style={{
              padding: '1rem 2rem',
              border: 'none',
              borderRadius: '10px',
              background: '#ce466f',
              color: 'white',
              cursor: 'pointer',
            }}
          >
            Get Started
          </button>
        </section>

        {/* PARALLAX WALL */}
        <Parallax translateY={['120px', '-80px']}>
          <section
            id="overview"
            style={{
              minHeight: '120vh',
              background: '#111',
              borderTopLeftRadius: '40px',
              borderTopRightRadius: '40px',
              padding: '5rem 3rem',
              position: 'relative',
              zIndex: 3,
            }}
          >
            <h2
              style={{
                fontSize: '3rem',
                marginBottom: '2rem',
              }}
            >
              Overview
            </h2>

            <p
              style={{
                maxWidth: '700px',
                lineHeight: '1.8',
              }}
            >
              This section now moves upward over the fixed LightPillar
              background while scrolling.
            </p>
          </section>
        </Parallax>

        {/* EXTRA SPACE */}
        <section
          style={{
            height: '100vh',
            background: '#0b0b0b',
          }}
        />

      </div>
    </ParallaxProvider>
  );
}

export default App;
